style.css:
@-moz-document domain("youtube.com") {
/* Genel Kırmızı Neon Tema */
    html, body {
        background-color: transparent !important;
        box-shadow: 0 0 30px rgba(255, 0, 0, 0.6) !important;
        color: #ff0000 !important;
    }

    /* Butonları Kırmızı Neon Yap */
    ytd-toggle-button-renderer,
    ytd-button-renderer,
    ytd-menu-renderer,
    #search-button,
    .ytd-mini-guide-renderer {
        background-color: transparent !important;
        border: 2px solid #ff0000 !important;
        color: #ff0000 !important;
        text-shadow: 0 0 5px #ff0000, 0 0 10px #ff0000, 0 0 20px #ff0000;
    }

    ytd-toggle-button-renderer:hover,
    ytd-button-renderer:hover,
    ytd-menu-renderer:hover {
        background-color: #ff0000 !important;
        color: #fff !important;
        text-shadow: 0 0 15px #ff0000, 0 0 25px #ff0000;
    }

    /* Neon Kırmızı Arama Çubuğu */
    #search-input {
        border: 2px solid #ff0000 !important;
        color: #ff0000 !important;
        background-color: transparent !important;
        box-shadow: 0 0 10px #ff0000, 0 0 20px #ff0000;
    }

    #search-input:focus {
        border-color: #ff0000 !important;
        box-shadow: 0 0 15px #ff0000;
    }

    /* Video Başlıkları ve Metinler Neon Kırmızı */
    ytd-video-primary-info-renderer,
    ytd-video-title,
    ytd-channel-name {
        color: #ff0000 !important;
        text-shadow: 0 0 5px #ff0000, 0 0 10px #ff0000, 0 0 20px #ff0000;
    }

    ytd-video-title:hover {
        text-decoration: underline !important;
        text-shadow: 0 0 20px #ff0000, 0 0 30px #ff0000;
    }

    /* Videoların Üzerine Gelince Neon Kırmızı Etkisi */
    ytd-thumbnail-overlay-time-status-renderer:hover,
    ytd-video-primary-info-renderer:hover {
        text-shadow: 0 0 15px #ff0000, 0 0 25px #ff0000;
        border: 2px solid #ff0000 !important;
    }

    /* Video Sayfasında Neon Kırmızı Efekti */
    ytd-player {
        box-shadow: 0 0 10px #ff0000, 0 0 20px #ff0000;
    }

    /* Sayfa Arka Planı ve Neon Çerçeve */
    .ytd-app {
        background: url('https://i.ytimg.com/vi/-MO-jn0L34U/hq720.jpg') no-repeat center center fixed;
        background-size: cover;
        border: 5px solid rgba(255, 0, 0, 0.8);
    }

    /* Koyu Mod Neon Kırmızı Etkisi */
    ytd-app {
        background-color: #121212 !important;
    }

    ytd-comment-renderer,
    ytd-video-meta-block {
        background-color: #1e1e1e !important;
        border: 1px solid #ff0000 !important;
    }

    ytd-comment-renderer:hover {
        background-color: #2b2b2b !important;
        box-shadow: 0 0 5px #ff0000, 0 0 15px #ff0000;
    }

    /* Pop-up ve Açılır Pencereler Neon Kırmızı */
    #comments-section,
    .ytd-watch-next-secondary-results-renderer {
        border: 2px solid #ff0000 !important;
        box-shadow: 0 0 15px #ff0000 !important;
    }

    .ytd-popup-container {
        border: 3px solid #ff0000;
        box-shadow: 0 0 10px #ff0000, 0 0 20px #ff0000;
    }

    /* Neon Arka Plan ve Işıldama Efekti */
    #masthead,
    #logo {
        background-color: transparent !important;
        box-shadow: 0 0 10px #ff0000, 0 0 20px #ff0000;
    }

    /* Tüm Metinlere Neon Kırmızı Efekti */
    ytd-video-meta-block,
    ytd-comment-renderer,
    ytd-video-primary-info-renderer {
        text-shadow: 0 0 5px #ff0000, 0 0 10px #ff0000, 0 0 15px #ff0000 !important;
    }

    /* Arama Sonuçları ve Videoların Listelendiği Alan Neon Kırmızı */
    ytd-rich-grid-media:hover,
    ytd-rich-grid-renderer:hover {
        border: 2px solid #ff0000 !important;
        box-shadow: 0 0 10px #ff0000, 0 0 20px #ff0000;
    }

    /* Video İzlerken Tüm Kenarlara Neon Etkisi */
    ytd-video-primary-info-renderer {
        border: 3px solid #ff0000;
        box-shadow: 0 0 10px #ff0000, 0 0 30px #ff0000;
    }

    /* Kenarlıklar ve Genel Çerçeve Neon Kırmızı */
    #page-manager {
        border: 2px solid #ff0000;
        box-shadow: 0 0 10px #ff0000, 0 0 20px #ff0000;
    }

    /* Video İzlerken Neon Kırmızı Çerçeve */
    .ytd-video-primary-info-renderer {
        box-shadow: 0 0 20px #ff0000, 0 0 40px #ff0000;
    }
}
